import i18n from '@dhis2/d2-i18n'
import { IconSearch16, InputField } from '@dhis2/ui'
import React, { useEffect } from 'react'
import { RefetchReports } from '../useReports'
import styles from './reportsSearchField.module.css'
import { useDebounce } from './use-debounce'

export const ReportsSearchField = ({
    refetchReports,
    searchTerm,
    setSearchTerm,
    order,
}: {
    refetchReports: RefetchReports
    searchTerm: undefined | string
    setSearchTerm: (s: undefined | string) => void
    order: string
}) => {
    // need to determine how to handle invalid entries on search term
    const debouncedValue = useDebounce(
        searchTerm?.trim()?.replaceAll(',', '')?.replaceAll(':', ''),
        300
    )

    const handleSearchChange = ({ value }: { value: undefined | string }) => {
        const validValue = value?.length ? value : undefined
        setSearchTerm(validValue)
    }

    useEffect(() => {
        // set to page:1 when search term changes to ensure that you see some results if they exist
        refetchReports({ searchTerm: debouncedValue, page: 1, order })
    }, [refetchReports, debouncedValue])

    return (
        <div className={styles.toolbar}>
            <div className={styles.search}>
                <InputField
                    dense
                    type="search"
                    /* @dhis2/ui types prefixIcon as `Element` (DOM), but it renders a React node. */
                    prefixIcon={(<IconSearch16 />) as unknown as Element}
                    value={searchTerm}
                    onChange={handleSearchChange}
                    placeholder={i18n.t('Search reports')}
                />
            </div>
        </div>
    )
}
