import i18n from '@dhis2/d2-i18n'
import { NoticeBox } from '@dhis2/ui'
import React from 'react'
import { useUserContext } from '../../../context'
import { Breadcrumbs } from '@/components'
import { Overview } from '@/pages/Overview/overview'

export const StandardReportManage = () => {
    const { canAdd, canDelete } = useUserContext()
    const hasNoAccess = !canAdd && !canDelete
    return (
        <div>
            <Breadcrumbs currentLocation={i18n.t('Manage standard reports')} />
            {hasNoAccess ? (
                <NoticeBox warning>
                    {i18n.t('You do not have access to this page')}
                </NoticeBox>
            ) : (
                <Overview manageView={true} />
            )}
        </div>
    )
}
