import { useConfig } from '@dhis2/app-runtime'
import type { FetchError } from '@dhis2/app-runtime'
import i18n from '@dhis2/d2-i18n'
import { CircularLoader, NoticeBox } from '@dhis2/ui'
import React, { useMemo } from 'react'
import styles from './HTMLReport.module.css'
import { wrapReportHtml } from './wrapReportHtml'

export const HTMLReport = ({
    html,
    loading,
    error,
}: {
    html?: string
    loading?: boolean
    error?: FetchError
}) => {
    const { baseUrl } = useConfig()
    const wrappedHtml = useMemo(
        () => (html ? wrapReportHtml(baseUrl, html) : undefined),
        [baseUrl, html]
    )

    if (loading) {
        return (
            <div className={styles.status}>
                <CircularLoader small />
            </div>
        )
    }

    if (error) {
        return (
            <div className={styles.status}>
                <NoticeBox
                    error
                    title={i18n.t('The report could not be generated')}
                >
                    {error.message}
                </NoticeBox>
            </div>
        )
    }

    if (!wrappedHtml) {
        return null
    }

    return (
        <iframe
            title={i18n.t('Report content')}
            className={styles.iframe}
            srcDoc={wrappedHtml}
            sandbox="allow-same-origin allow-scripts allow-modals allow-downloads"
        />
    )
}
