import { useField } from 'react-final-form'
import { usePeriod } from '../../../../context'

// common modified period input field for keeping context in sync
export const usePeriodField = () => {
    const [, setPeriod] = usePeriod()
    const { input: periodInput, meta: periodMeta } = useField('period', {
        subscription: { value: true },
    })
    const modifiedInput = {
        ...periodInput,
        onChange: (value: string) => {
            setPeriod(value)
            periodInput.onChange(value)
        },
    }
    return { periodInput, periodMeta, modifiedInput, setPeriod }
}
