// keyed by relative period, e.g. `thisMonth` (see @/constants/relativePeriods)
type RelativePeriods = Record<string, boolean>

export const queryFields = [
    'displayName',
    'id',
    'created',
    'lastUpdated',
    'reportParams[organisationUnit,reportingPeriod],relativePeriods',
]

export interface Report {
    displayName: string
    id: string
    created: string
    lastUpdated: string
    reportParams: {
        organisationUnit: boolean
        reportingPeriod: boolean
    }
    relativePeriods: RelativePeriods
}
export type ReportInfoQueryResponse = {
    report: Report
}
