import { useDataQuery } from '@dhis2/app-runtime'
// @ts-expect-error -- `/experimental` is a package `exports` subpath, which this
// tsconfig's moduleResolution can't resolve. Its PluginProps also doesn't type
// the arbitrary props forwarded to the plugin, so it would be `any` here anyway.
import { Plugin } from '@dhis2/app-runtime/experimental'
import {
    CircularLoader,
    DataTable,
    DataTableBody,
    DataTableCell,
    DataTableColumnHeader,
    DataTableHead,
    DataTableRow,
    InputField,
    NoticeBox,
    SegmentedControl,
} from '@dhis2/ui'
import React, { useCallback, useEffect, useRef, useState } from 'react'
import { Form } from 'react-final-form'
import {
    ArrayParam,
    BooleanParam,
    StringParam,
    useQueryParams,
    withDefault,
} from 'use-query-params'
import { useFormData, type FormDataStats } from './formData'
import styles from './FormPluginSpike.module.css'
import { useFormSelection, type Selection } from './formSelection'
import { SpikeParameters } from './SpikeParameters'
import { ParameterItem, ReportDefaultLayout } from '@/components'
import { toDhis2PeriodId } from '@/pages/StandardReport/view/parametersSelector/fixedPeriods/periodTypeMapping'
import type { DynamicResourceQuery, QueryVariables } from '@/types/query'

/*
 * SPIKE (DHIS2-22048): a data set report with two views, Summary (the
 * `/api/dataSetReport` tables) and Data entry form (the data entry app's data
 * workspace as a plugin). Exists to answer the spike's questions; not wired
 * into the real data set report page.
 *
 * Uses the same layout as the other reports. The parameters panel has real
 * data set, org unit and period selectors (SpikeParameters.tsx); the
 * selection is kept in the URL with the same names as `/api/dataSetReport`
 * takes (`ds`, `pe`, `ou`, `selectedUnitOnly`), e.g.
 * #/dataSetReports/spike/form-plugin?ds=BfMAe6Itzgt&pe=202401&ou=DiszpKrYNg8
 *
 * Once the plugin has loaded, a new selection is sent to it as new props
 * rather than by reloading the iframe, to see whether the workspace can
 * follow the host's selection.
 *
 * Note the form view does not show the report's numbers: the plugin fetches
 * its own raw values for the org unit and period.
 */

// The installed data entry app doesn't have the spike's DATA_WORKSPACE mode,
// so load it from the spike branch's dev server. It must run on an origin the
// instance's CORS allowlist accepts (play dev: e.g. port 9000). Clear the field
// under "Spike details" to load the installed app by short name instead.
const DEFAULT_PLUGIN_SOURCE = 'http://localhost:9000/plugin.html'

// Sierra Leone demo: Child Health, Ngelehun CHC
const DEFAULT_PARAMS = {
    ds: 'BfMAe6Itzgt',
    pe: '202401',
    ou: 'DiszpKrYNg8',
}

const VIEWS = { SUMMARY: 'summary', FORM: 'form' }

type ReportGrid = {
    title: string
    subtitle?: string
    headers: {
        name: string
        column: string
        meta?: boolean
        hidden?: boolean
    }[]
    rows: (string | null)[][]
}

type Timing = { event: string; at: number }

type ReportStats = {
    ms: number
    tables: number
    rows: number
    metaDataKeys: number
}

// Attribute options are kept as `/api/dataSetReport` takes them,
// `categoryId:optionId`, and as `{ categoryId: optionId }` everywhere else
// (the form, and the plugin's attributeOptionComboSelection).
type Attributes = Record<string, string>

const toFilter = (attributes: Attributes) =>
    Object.entries(attributes).map(
        ([category, option]) => `${category}:${option}`
    )

const fromFilter = (filter: (string | null)[] | null | undefined) =>
    Object.fromEntries(
        (filter ?? [])
            .map((item) => item?.split(':') ?? [])
            .filter((pair) => pair.length === 2 && pair[0] && pair[1])
    ) as Attributes

const REPORT_QUERY: Record<string, DynamicResourceQuery> = {
    report: {
        resource: 'dataSetReport',
        params: ({ ds, pe, ou, selectedUnitOnly, filter }: QueryVariables) => ({
            ds,
            pe,
            ou,
            selectedUnitOnly,
            ...(filter ? { filter } : {}),
        }),
    } as unknown as DynamicResourceQuery,
    dataSet: {
        resource: 'dataSets',
        id: ({ ds }: QueryVariables) => ds,
        params: {
            fields: 'displayName,periodType',
        },
    },
}

type ReportResponse = {
    report: (ReportGrid & { metaData?: Record<string, unknown> })[]
    dataSet: { displayName: string; periodType: string }
}

const SummaryView = ({ grids }: { grids: ReportGrid[] }) => (
    <div className={styles.sections}>
        {grids.map((grid) => {
            const visible = grid.headers
                .map((header, position) => ({ header, position }))
                .filter(({ header }) => !header.hidden)
            return (
                <section key={grid.title}>
                    <h3 className={styles.sectionTitle}>{grid.title}</h3>
                    <DataTable className={styles.table}>
                        <DataTableHead>
                            <DataTableRow>
                                {visible.map(({ header, position }) => (
                                    <DataTableColumnHeader
                                        key={position}
                                        align={
                                            position === 0 ? 'left' : 'right'
                                        }
                                    >
                                        {header.column || header.name}
                                    </DataTableColumnHeader>
                                ))}
                            </DataTableRow>
                        </DataTableHead>
                        <DataTableBody>
                            {grid.rows.map((cells) => (
                                // the first cell is the data element name
                                <DataTableRow key={cells[0]}>
                                    {visible.map(({ position }) => (
                                        <DataTableCell
                                            key={position}
                                            align={
                                                position === 0
                                                    ? 'left'
                                                    : 'right'
                                            }
                                        >
                                            {cells[position] || '–'}
                                        </DataTableCell>
                                    ))}
                                </DataTableRow>
                            ))}
                        </DataTableBody>
                    </DataTable>
                </section>
            )
        })}
    </div>
)

const REQUIRED = {
    ou: 'an organisation unit',
    ds: 'a data set',
    pe: 'a period',
} as const

const validate = (values: FormValues) =>
    Object.fromEntries(
        Object.entries(REQUIRED)
            .filter(([name]) => !values[name as keyof typeof REQUIRED])
            .map(([name, label]) => [name, `Choose ${label}`])
    )

type FormValues = {
    ds?: string
    pe?: string
    ou?: string
    selectedUnitOnly: boolean
    attributes: Attributes
}

const SpikeDetails = ({
    pluginSource,
    setPluginSource,
    timings,
    pluginProps,
    selectedUnitOnly,
    reportStats,
    formDataStats,
}: {
    pluginSource: string
    setPluginSource: (value: string) => void
    timings: Timing[]
    pluginProps: Record<string, string | undefined>
    selectedUnitOnly: boolean
    reportStats?: ReportStats
    formDataStats: FormDataStats
}) => (
    <ParameterItem>
        <details className={styles.spikeDetails}>
            <summary>Spike details</summary>
            <InputField
                dense
                label="pluginSource (empty: installed app by short name)"
                value={pluginSource}
                onChange={({ value }) => setPluginSource(value ?? '')}
            />

            <h4 className={styles.spikeHeading}>Sent to the plugin</h4>
            <dl className={styles.spikeList}>
                {Object.entries(pluginProps).map(([name, value]) => (
                    <React.Fragment key={name}>
                        <dt>{name}</dt>
                        <dd>{value || '–'}</dd>
                    </React.Fragment>
                ))}
            </dl>
            <p className={styles.spikeNote}>
                {selectedUnitOnly
                    ? 'Both views show this org unit only.'
                    : 'Summary adds up units inside; the form shows values stored on this org unit only, so they can differ.'}
            </p>

            <h4 className={styles.spikeHeading}>Summary request</h4>
            {reportStats ? (
                <dl className={styles.spikeList}>
                    <dt>dataSetReport</dt>
                    <dd>{reportStats.ms.toFixed(0)} ms</dd>
                    <dt>Tables</dt>
                    <dd>{reportStats.tables}</dd>
                    <dt>Rows</dt>
                    <dd>{reportStats.rows}</dd>
                    <dt>metaData keys</dt>
                    <dd>
                        {reportStats.metaDataKeys}
                        {reportStats.metaDataKeys === 0 &&
                            ' (no IDs to map cells to fields)'}
                    </dd>
                </dl>
            ) : (
                <p className={styles.spikeNote}>Not fetched yet</p>
            )}

            <h4 className={styles.spikeHeading}>
                Form values (fetched by the reports app)
            </h4>
            {formDataStats.dataValuesMs === undefined ? (
                <p className={styles.spikeNote}>Not fetched yet</p>
            ) : (
                <dl className={styles.spikeList}>
                    <dt>
                        {formDataStats.dataValuesSource ??
                            'dataEntry/dataValues'}
                    </dt>
                    <dd>
                        {`${formDataStats.dataValuesMs.toFixed(0)} ms, ${
                            formDataStats.dataValues ?? 0
                        } values`}
                    </dd>
                </dl>
            )}

            <h4 className={styles.spikeHeading}>
                Plugin timings (from opening the form view)
            </h4>
            <ul className={styles.spikeTimings}>
                {timings.length === 0 && <li>None yet</li>}
                {timings.map((t, i) => (
                    <li key={i}>
                        {t.event}: {t.at.toFixed(0)} ms
                        {i > 0 &&
                            ` (+${(t.at - timings[i - 1].at).toFixed(0)})`}
                    </li>
                ))}
            </ul>
        </details>
    </ParameterItem>
)

export const FormPluginSpike = () => {
    const [params, setParams] = useQueryParams({
        ds: StringParam,
        pe: StringParam,
        ou: StringParam,
        selectedUnitOnly: withDefault(BooleanParam, false),
        filter: ArrayParam,
        view: withDefault(StringParam, VIEWS.SUMMARY),
    })
    // Start on the demo selection when the URL has none. Not withDefault: that
    // would also bring it back whenever a parameter is cleared.
    const [startsEmpty] = useState(!params.ds && !params.pe && !params.ou)
    useEffect(() => {
        if (startsEmpty) {
            setParams(DEFAULT_PARAMS, 'replaceIn')
        }
    }, [startsEmpty, setParams])
    const { ds, ou, selectedUnitOnly, view } = params
    // older links have the library's November IDs
    const pe = params.pe ? toDhis2PeriodId(params.pe) : params.pe
    const filterKey = (params.filter ?? []).join()
    const isComplete = Boolean(ds && pe && ou)
    // e.g. a shared link with the period left out
    const missingFromUrl = Object.entries(REQUIRED)
        .filter(([name]) => !params[name as keyof typeof REQUIRED])
        .map(([, label]) => label)
    const isPartial = !isComplete && missingFromUrl.length < 3
    const [initialValues] = useState<FormValues>(() => ({
        ...(startsEmpty ? DEFAULT_PARAMS : { ds, pe, ou }),
        selectedUnitOnly,
        attributes: fromFilter(params.filter),
    }))
    const attributes = fromFilter(params.filter)

    const { data, loading, error, refetch } = useDataQuery<ReportResponse>(
        REPORT_QUERY,
        { lazy: true }
    )
    const [timestamp, setTimestamp] = useState<number>()
    const requestedAt = useRef(0)
    useEffect(() => {
        if (!isComplete) {
            return
        }
        requestedAt.current = performance.now()
        refetch({
            ds,
            pe,
            ou,
            selectedUnitOnly,
            filter: filterKey || undefined,
        })
        setTimestamp(Date.now())
    }, [ds, pe, ou, selectedUnitOnly, filterKey, isComplete, refetch])

    const [reportStats, setReportStats] = useState<ReportStats>()
    useEffect(() => {
        if (!data) {
            return
        }
        setReportStats({
            ms: performance.now() - requestedAt.current,
            tables: data.report.length,
            rows: data.report.reduce((sum, grid) => sum + grid.rows.length, 0),
            metaDataKeys: data.report.reduce(
                (sum, grid) => sum + Object.keys(grid.metaData ?? {}).length,
                0
            ),
        })
    }, [data])

    const selection: Selection | undefined =
        ds && pe && ou ? { ds, pe, ou, attributes } : undefined
    const formCheck = useFormSelection(selection)
    const dataSetPeriodTypeLabel =
        data?.dataSet.periodType.toLowerCase() ?? 'per period'
    const problems = formCheck.problems.map(({ message }) => message)

    const [pluginSource, setPluginSource] = useState(DEFAULT_PLUGIN_SOURCE)
    // Lazy: the plugin is only loaded once someone opens the form view, then
    // kept mounted so switching back and forth doesn't reload it.
    const [formOpened, setFormOpened] = useState(view === VIEWS.FORM)

    const formData = useFormData({
        enabled: formOpened,
        selection: formCheck.formSelection,
        params: formCheck.dataValuesParams,
        totals: formCheck.totals,
        dataElements: formCheck.dataElements,
    })
    const formSelection = formData.loaded?.selection
    const showsForm =
        formCheck.ready &&
        !formData.loading &&
        !formData.error &&
        JSON.stringify(formSelection) ===
            JSON.stringify(formCheck.formSelection)
    const [timings, setTimings] = useState<Timing[]>([])
    const startedAt = useRef(0)

    const onTiming = useCallback((timing: Timing) => {
        setTimings((prev) => [
            ...prev,
            { event: timing.event, at: performance.now() - startedAt.current },
        ])
    }, [])

    // logged on the host side only
    const sentSelection = useRef('')
    useEffect(() => {
        const sent = JSON.stringify(formSelection ?? null)
        if (formOpened && formSelection && sentSelection.current !== sent) {
            if (sentSelection.current) {
                onTiming({ event: `propsUpdated ${sent}`, at: 0 })
            }
            sentSelection.current = sent
        }
    }, [formSelection, formOpened, onTiming])

    const onChangeView = ({ value }: { value: string }) => {
        if (value === VIEWS.FORM && !formOpened) {
            startedAt.current = performance.now()
            setTimings([])
            setFormOpened(true)
        }
        setParams({ view: value })
    }

    let summary = <CircularLoader />
    if (error) {
        summary = (
            <NoticeBox error title="Report failed">
                {error.message}
            </NoticeBox>
        )
    } else if (data && !loading) {
        summary = <SummaryView grids={data.report} />
    }

    const reportContent = isPartial ? (
        <div className={styles.body}>
            <NoticeBox warning title="This report is missing parameters">
                {`Choose ${missingFromUrl.join(', ')}, then Get report.`}
            </NoticeBox>
        </div>
    ) : (
        <>
            <div className={styles.viewBar}>
                <span className={styles.viewLabel}>View as:</span>
                <SegmentedControl
                    selected={view}
                    onChange={onChangeView}
                    options={[
                        { label: 'Summary', value: VIEWS.SUMMARY },
                        { label: 'Data entry form', value: VIEWS.FORM },
                    ]}
                />
            </div>

            <div className={styles.body}>
                {view === VIEWS.SUMMARY && summary}

                {view === VIEWS.FORM && showsForm && formCheck.totals && (
                    <p className={styles.formTotals}>
                        {`Totals for the whole period, added up like the summary. ${
                            data?.dataSet.displayName ?? 'The data set'
                        } is collected ${dataSetPeriodTypeLabel}; text and yes/no fields can't be added up, so they're empty.`}
                    </p>
                )}

                {view === VIEWS.FORM &&
                    (formCheck.checking || formData.loading) && (
                        <CircularLoader />
                    )}

                {view === VIEWS.FORM && formData.error && (
                    <NoticeBox error title="The form couldn't be loaded">
                        {formData.error}
                    </NoticeBox>
                )}

                {view === VIEWS.FORM && problems.length > 0 && (
                    <NoticeBox title="No data entry form for this selection">
                        {problems.length === 1 ? (
                            problems[0]
                        ) : (
                            <ul className={styles.problems}>
                                {problems.map((problem) => (
                                    <li key={problem}>{problem}</li>
                                ))}
                            </ul>
                        )}
                    </NoticeBox>
                )}
                {formOpened && formData.loaded && (
                    <div
                        className={styles.formView}
                        hidden={view !== VIEWS.FORM || !showsForm}
                    >
                        <Plugin
                            // only a new source reloads the iframe; a new
                            // selection is sent to the loaded plugin
                            key={pluginSource}
                            {...(pluginSource
                                ? { pluginSource }
                                : { pluginShortName: 'aggregate-data-entry' })}
                            className={styles.plugin}
                            onLoad={() =>
                                onTiming({ event: 'iframeLoad', at: 0 })
                            }
                            pluginMode="DATA_WORKSPACE"
                            readOnly
                            dataSetId={formData.loaded.selection.ds}
                            orgUnitId={formData.loaded.selection.ou}
                            periodId={formData.loaded.selection.pe}
                            attributeOptionComboSelection={
                                formData.loaded.selection.attributes
                            }
                            dataValues={formData.loaded.dataValues}
                        />
                    </div>
                )}
            </div>
        </>
    )

    return (
        <Form<FormValues>
            initialValues={initialValues}
            validate={validate}
            onSubmit={(values, form) => {
                const filter = toFilter(values.attributes ?? {})
                setParams({
                    ds: values.ds,
                    pe: values.pe,
                    ou: values.ou,
                    selectedUnitOnly: values.selectedUnitOnly,
                    filter: filter.length > 0 ? filter : undefined,
                })
                form.initialize(values)
            }}
            render={({ handleSubmit, form }) => (
                <ReportDefaultLayout
                    currentLocationString="Data set report (spike)"
                    ParametersSelector={
                        <SpikeParameters
                            formView={view === VIEWS.FORM}
                            spikeDetails={
                                <SpikeDetails
                                    pluginSource={pluginSource}
                                    setPluginSource={setPluginSource}
                                    timings={timings}
                                    pluginProps={{
                                        pluginMode: 'DATA_WORKSPACE',
                                        readOnly: 'true',
                                        dataValues: formData.loaded
                                            ? `${
                                                  formData.loaded.dataValues
                                                      .dataValues?.length ?? 0
                                              } values`
                                            : undefined,
                                        dataSetId: formSelection?.ds,
                                        orgUnitId: formSelection?.ou,
                                        periodId: formSelection?.pe,
                                        attributeOptionComboSelection: toFilter(
                                            formSelection?.attributes ?? {}
                                        ).join(', '),
                                    }}
                                    selectedUnitOnly={selectedUnitOnly}
                                    reportStats={reportStats}
                                    formDataStats={formData.stats}
                                />
                            }
                        />
                    }
                    ReportContent={reportContent}
                    isEmpty={!isComplete && !isPartial}
                    reportName={data?.dataSet.displayName}
                    generatedParams={{ period: pe, orgUnit: ou, timestamp }}
                    onSubmit={handleSubmit}
                    onParametersClear={() =>
                        form.batch(() => {
                            form.change('ds', undefined)
                            form.change('pe', undefined)
                            form.change('ou', undefined)
                            form.change('selectedUnitOnly', false)
                            form.change('attributes', {})
                        })
                    }
                />
            )}
        />
    )
}
