import { useConfig } from '@dhis2/app-runtime'
import i18n from '@dhis2/d2-i18n'
import {
    Button,
    ButtonStrip,
    FileInputField,
    FileInputFieldFF,
    FileListItem,
    InputFieldFF,
    NoticeBox,
    SingleSelectFieldFF,
    hasValue,
} from '@dhis2/ui'
import React, { useMemo } from 'react'
import { Field, Form, useField } from 'react-final-form'
import { useNavigate } from 'react-router-dom'
import { CheckboxGroup } from './CheckboxGroup'
import { FormColumn } from './FormPage'
import { CACHE_STRATEGIES, REPORT_PARAMETERS } from './options'
import {
    NEW_REPORT_VALUES,
    StoredReport,
    toFormValues,
} from './reportFormValues'
import styles from './StandardReportForm.module.css'
import { MANAGE_PATH, useSaveReport } from './useSaveReport'
import { ErrorReportList } from '@/components'
import { RELATIVE_PERIODS } from '@/constants/relativePeriods'

const Section = ({
    title,
    hint,
    children,
}: { title: string; hint?: string } & React.PropsWithChildren) => (
    <section className={styles.section}>
        <p className={styles.sectionTitle}>{title}</p>
        {hint && <p className={styles.sectionHint}>{hint}</p>}
        {children}
    </section>
)

const DesignFileField = ({ report }: { report?: StoredReport }) => {
    const { baseUrl } = useConfig()
    const { input: keepCurrentDesign } = useField<boolean>(
        'keepCurrentDesign',
        { subscription: { value: true } }
    )

    if (report && keepCurrentDesign.value) {
        return (
            <>
                <FileInputField
                    className={styles.field}
                    label={i18n.t('Design file')}
                    buttonLabel={i18n.t('Select file')}
                    helpText={i18n.t(
                        'Remove the current design to upload a new one.'
                    )}
                    required
                    disabled
                >
                    <FileListItem
                        label={`${report.name}.html`}
                        removeText={i18n.t('Remove')}
                        onRemove={() => keepCurrentDesign.onChange(false)}
                    />
                </FileInputField>
                <a
                    className={styles.downloadLink}
                    href={`${baseUrl}/api/reports/${report.id}/design`}
                >
                    {i18n.t('Download current design')}
                </a>
            </>
        )
    }

    return (
        <Field
            name="designFile"
            component={FileInputFieldFF}
            className={styles.field}
            label={i18n.t('Design file')}
            buttonLabel={i18n.t('Select file')}
            accept=".html,.htm"
            helpText={i18n.t(
                'The HTML design file that defines the report layout.'
            )}
            required
            validate={hasValue}
        />
    )
}

/* Creates a new report, or edits `existingReport` when one is given */
export const StandardReportForm = ({
    existingReport,
}: {
    existingReport?: StoredReport
}) => {
    const isEdit = Boolean(existingReport)
    const navigate = useNavigate()
    const { save, loading, error } = useSaveReport(existingReport)
    const initialValues = useMemo(
        () =>
            existingReport ? toFormValues(existingReport) : NEW_REPORT_VALUES,
        [existingReport]
    )

    return (
        <Form onSubmit={save} initialValues={initialValues}>
            {({ handleSubmit, submitting }) => (
                <form onSubmit={handleSubmit} className={styles.form}>
                    <FormColumn>
                        <p className={styles.title}>
                            {isEdit
                                ? i18n.t('Edit standard report')
                                : i18n.t('New standard report')}
                        </p>
                        <p className={styles.description}>
                            {isEdit
                                ? i18n.t(
                                      'Change what this report is called, what it asks for before it runs, and how long a generated copy may be reused. Fields marked with * are required.'
                                  )
                                : i18n.t(
                                      'Register a report design so it can be run against current data. Fields marked with * are required.'
                                  )}
                        </p>

                        <Section title={i18n.t('Details')}>
                            <Field
                                name="name"
                                component={InputFieldFF}
                                className={styles.field}
                                label={i18n.t('Name')}
                                helpText={i18n.t(
                                    'Displayed in the standard report list.'
                                )}
                                required
                                validate={hasValue}
                            />
                            <Field
                                name="code"
                                component={InputFieldFF}
                                className={styles.field}
                                label={i18n.t('Code')}
                            />
                            <DesignFileField report={existingReport} />
                        </Section>

                        <Section
                            title={i18n.t('Report parameters')}
                            hint={i18n.t(
                                'Selected parameters are requested when the report is run.'
                            )}
                        >
                            <CheckboxGroup
                                name="reportParams"
                                options={REPORT_PARAMETERS}
                                inline
                            />
                        </Section>

                        <Section
                            title={i18n.t('Relative periods')}
                            hint={i18n.t(
                                'The relative periods users can choose from when running the report.'
                            )}
                        >
                            <div className={styles.periodGroups}>
                                {RELATIVE_PERIODS.map(({ label, options }) => (
                                    <CheckboxGroup
                                        key={label}
                                        name="relativePeriods"
                                        title={label}
                                        options={options}
                                    />
                                ))}
                            </div>
                        </Section>

                        <Section title={i18n.t('Settings')}>
                            <Field
                                name="cacheStrategy"
                                component={SingleSelectFieldFF}
                                className={styles.field}
                                label={i18n.t('Cache strategy')}
                                helpText={i18n.t(
                                    'How long a generated report may be reused before it is regenerated.'
                                )}
                                options={CACHE_STRATEGIES}
                                required
                                validate={hasValue}
                            />
                        </Section>

                        {error && (
                            <NoticeBox
                                error
                                title={
                                    isEdit
                                        ? i18n.t(
                                              'The report could not be updated'
                                          )
                                        : i18n.t(
                                              'The report could not be created'
                                          )
                                }
                            >
                                {error.message}
                                <ErrorReportList error={error} />
                            </NoticeBox>
                        )}
                    </FormColumn>

                    {/* Pinned below the scrolling column, so the actions stay in view */}
                    <footer className={styles.actions}>
                        <div className={styles.column}>
                            <ButtonStrip>
                                <Button
                                    primary
                                    type="submit"
                                    loading={submitting || loading}
                                >
                                    {isEdit
                                        ? i18n.t('Save changes')
                                        : i18n.t('Create report')}
                                </Button>
                                <Button
                                    secondary
                                    disabled={submitting || loading}
                                    onClick={() => navigate(MANAGE_PATH)}
                                >
                                    {i18n.t('Cancel')}
                                </Button>
                            </ButtonStrip>
                        </div>
                    </footer>
                </form>
            )}
        </Form>
    )
}
