import i18n from '@dhis2/d2-i18n'
import React from 'react'
import styles from './StandardReportForm.module.css'
import { MANAGE_PATH } from './useSaveReport'
import { Breadcrumbs } from '@/components'

/* Full-height page: the breadcrumbs stay on top while the content below scrolls */
export const FormPage = ({
    title,
    children,
}: { title: string } & React.PropsWithChildren) => (
    <div className={styles.page}>
        <Breadcrumbs
            currentLocation={title}
            additionalPath={{ location: MANAGE_PATH, text: i18n.t('Manage') }}
        />
        {children}
    </div>
)

/* The scrolling area, with its content in a centred column */
export const FormColumn = ({ children }: React.PropsWithChildren) => (
    <div className={styles.scroll}>
        <div className={styles.column}>{children}</div>
    </div>
)
