import { useDataEngine } from '@dhis2/app-runtime'
import { useEffect, useState } from 'react'
import type { DataValuesParams, Selection } from './formSelection'

/*
 * SPIKE (DHIS2-22048): fetches the form's values, so failures show in the
 * report rather than in the plugin. Values come from dataEntry/dataValues,
 * or from analytics as totals for a longer period (dataSetReport has no IDs
 * to match the form's fields). The plugin fetches the form layout itself.
 */

type DataValues = { dataValues?: unknown[] }

export type FormData = {
    selection: Selection
    dataValues: DataValues
}

export type FormDataStats = {
    dataValuesMs?: number
    dataValues?: number
    dataValuesSource?: 'dataEntry/dataValues' | 'analytics'
}

const errorMessage = (error: unknown) =>
    error instanceof Error ? error.message : String(error)

type AnalyticsResponse = {
    headers: { name: string }[]
    rows: string[][]
}

// the plugin reads these too, e.g. minMaxValues.find in every number field
const EMPTY_DATA_VALUES = {
    minMaxValues: [],
    lockStatus: 'OPEN',
    completeStatus: { complete: false },
}

// shaped like a dataValues response; only numbers add up
const fetchTotals = async (
    engine: ReturnType<typeof useDataEngine>,
    dataElements: string[],
    { pe, ou, attributes }: Selection
): Promise<DataValues> => {
    if (dataElements.length === 0) {
        return { ...EMPTY_DATA_VALUES, dataValues: [] }
    }
    const { totals } = (await engine.query({
        totals: {
            resource: 'analytics',
            params: {
                // comma-joined; analytics reads it as two dimensions
                dimension: [`dx:${dataElements.join(';')}`, 'co'],
                filter: [
                    `pe:${pe}`,
                    `ou:${ou}`,
                    ...Object.entries(attributes).map(
                        ([category, option]) => `${category}:${option}`
                    ),
                ],
                skipMeta: true,
            },
        },
    })) as { totals: AnalyticsResponse }
    const column = (name: string) =>
        totals.headers.findIndex((header) => header.name === name)
    const [dx, co, value] = [column('dx'), column('co'), column('value')]
    return {
        ...EMPTY_DATA_VALUES,
        dataValues: totals.rows.map((row) => ({
            dataElement: row[dx],
            categoryOptionCombo: row[co],
            value: row[value],
        })),
    }
}

export const useFormData = ({
    enabled,
    selection,
    params,
    totals,
    dataElements,
}: {
    enabled: boolean
    selection?: Selection
    params?: DataValuesParams
    totals: boolean
    dataElements?: string[]
}) => {
    const engine = useDataEngine()

    const key = params ? JSON.stringify({ ...params, totals }) : ''
    const [values, setValues] = useState<{
        key: string
        selection: Selection
        totals: boolean
        data?: DataValues
        error?: string
        ms?: number
    }>()
    useEffect(() => {
        if (!enabled || !params || !selection) {
            return
        }
        let current = true
        const startedAt = performance.now()
        const request = totals
            ? fetchTotals(engine, dataElements ?? [], selection)
            : engine
                  .query({
                      dataValues: { resource: 'dataEntry/dataValues', params },
                  })
                  .then(({ dataValues: data }) => data as DataValues)
        request
            .then((data) => {
                if (current) {
                    setValues({
                        key,
                        selection,
                        totals,
                        data,
                        ms: performance.now() - startedAt,
                    })
                }
            })
            .catch((error) => {
                if (current) {
                    setValues({
                        key,
                        selection,
                        totals,
                        error: errorMessage(error),
                    })
                }
            })
        return () => {
            current = false
        }
        // key stands in for params, totals, selection and dataElements
    }, [enabled, key, engine])

    const valuesForKey = values?.key === key ? values : undefined
    const error = valuesForKey?.error
    const loading = Boolean(params) && !error && !valuesForKey?.data

    // the last complete set, kept while a newer selection loads
    const [loaded, setLoaded] = useState<FormData>()
    useEffect(() => {
        if (valuesForKey?.data) {
            setLoaded({
                selection: valuesForKey.selection,
                dataValues: valuesForKey.data,
            })
        }
    }, [valuesForKey?.data])

    const stats: FormDataStats = {
        dataValuesMs: values?.ms,
        dataValues: values?.data?.dataValues?.length,
        dataValuesSource: values
            ? values.totals
                ? 'analytics'
                : 'dataEntry/dataValues'
            : undefined,
    }
    return { loading, error, loaded, stats }
}
