import { CheckboxFieldFF } from '@dhis2/ui'
import React from 'react'
import { Field } from 'react-final-form'
import styles from './StandardReportForm.module.css'

type Option = { value: string; label: string }

/* One checkbox per option, each bound to `${name}.${option.value}` as a boolean */
export const CheckboxGroup = ({
    name,
    title,
    options,
    inline = false,
}: {
    name: string
    title?: string
    options: Option[]
    inline?: boolean
}) => (
    <fieldset
        className={
            inline
                ? `${styles.checkboxGroup} ${styles.inline}`
                : styles.checkboxGroup
        }
    >
        {title && (
            <legend className={styles.checkboxGroupTitle}>{title}</legend>
        )}
        {options.map(({ value, label }) => (
            <Field
                key={value}
                name={`${name}.${value}`}
                type="checkbox"
                component={CheckboxFieldFF}
                label={label}
                dense
            />
        ))}
    </fieldset>
)
