import { useConfig, useDataQuery } from '@dhis2/app-runtime'
import { createFixedPeriodFromPeriodId } from '@dhis2/multi-calendar-dates'
import {
    CircularLoader,
    OrganisationUnitTree,
    Radio,
    SingleSelectField,
    SingleSelectOption,
} from '@dhis2/ui'
import React, { useEffect, useState } from 'react'
import { useField } from 'react-final-form'
import styles from './FormPluginSpike.module.css'
import { ParameterItem } from '@/components'
import { useUserContext } from '@/context'
import {
    PERIODS_ORDER,
    toLibraryPeriodId,
    toMultiCalendarPeriodType,
} from '@/pages/StandardReport/view/parametersSelector/fixedPeriods/periodTypeMapping'
import { useFixedPeriods } from '@/pages/StandardReport/view/parametersSelector/fixedPeriods/useFixedPeriods'
import type { DynamicResourceQuery, QueryVariables } from '@/types/query'

/*
 * SPIKE (DHIS2-22048): real selectors for the spike's parameters, so the
 * plugin can be driven with whatever the user picks rather than fixed IDs.
 * Form fields keep the `/api/dataSetReport` names (`ds`, `pe`, `ou`), all
 * plain IDs. Laid out like the prototype's parameter rail (reports-app,
 * prototype/redesign: data-set-report-next/DataSetReportNext.jsx).
 */

// not exported by @dhis2/multi-calendar-dates, so derived structurally from
// a function that uses it
type SupportedCalendar = Parameters<
    typeof createFixedPeriodFromPeriodId
>[0]['calendar']

type Option = { id: string; displayName: string }

export type AttributeCategory = Option & { categoryOptions: Option[] }

type DataSet = {
    id: string
    displayName: string
    periodType: string
    categoryCombo: { isDefault: boolean; categories: AttributeCategory[] }
}

const DATA_SETS_QUERY = {
    dataSets: {
        resource: 'dataSets',
        params: {
            fields: 'id,displayName,periodType,categoryCombo[isDefault,categories[id,displayName,categoryOptions[id,displayName]]]',
            order: 'displayName:asc',
            paging: false,
        },
    },
}

const PERIOD_TYPES_QUERY = {
    periodTypes: {
        resource: 'periodTypes',
        params: { fields: 'name,displayName' },
    },
}

const ORG_UNIT_PATH_QUERY: { orgUnit: DynamicResourceQuery } = {
    orgUnit: {
        resource: 'organisationUnits',
        id: ({ id }: QueryVariables) => id ?? '',
        params: { fields: 'path' },
    },
}

const useCalendar = (): SupportedCalendar =>
    ((useConfig().systemInfo as { calendar?: string } | undefined)?.calendar ??
        'gregory') as SupportedCalendar

const parsePeriod = (periodId: string, calendar: SupportedCalendar) => {
    try {
        return createFixedPeriodFromPeriodId({
            periodId: toLibraryPeriodId(periodId),
            calendar,
        })
    } catch {
        return undefined
    }
}

// same wording as the prototype's `cadenceLabel`
const cadenceLabel = (periodType: string) => {
    switch (periodType) {
        case 'Daily':
            return 'Data collected daily'
        case 'Weekly':
        case 'WeeklyWednesday':
        case 'WeeklyThursday':
        case 'WeeklySaturday':
        case 'WeeklySunday':
            return 'Data collected weekly'
        case 'BiWeekly':
            return 'Data collected every two weeks'
        case 'Monthly':
            return 'Data collected monthly'
        case 'BiMonthly':
            return 'Data collected every two months'
        case 'Quarterly':
        case 'QuarterlyNov':
            return 'Data collected quarterly'
        case 'SixMonthly':
        case 'SixMonthlyApril':
        case 'SixMonthlyNov':
            return 'Data collected twice a year'
        case 'Yearly':
        case 'FinancialApril':
        case 'FinancialJuly':
        case 'FinancialOct':
        case 'FinancialNov':
            return 'Data collected yearly'
        default:
            return periodType
    }
}

const YEARS_OF_HISTORY = 10

/*
 * Roughly how long each period type lasts, in days, only to compare types
 * with each other (from the prototype's periods.js `LENGTH_IN_DAYS`).
 */
const LENGTH_IN_DAYS: Record<string, number> = {
    Daily: 1,
    Weekly: 7,
    WeeklyWednesday: 7,
    WeeklyThursday: 7,
    WeeklySaturday: 7,
    WeeklySunday: 7,
    BiWeekly: 14,
    Monthly: 30,
    BiMonthly: 60,
    Quarterly: 91,
    QuarterlyNov: 91,
    SixMonthly: 182,
    SixMonthlyApril: 182,
    SixMonthlyNov: 182,
    Yearly: 365,
    FinancialApril: 365,
    FinancialJuly: 365,
    FinancialOct: 365,
    FinancialNov: 365,
}

// Data collected per `dataSetPeriodType` can be added up into `periodType`
// only if that's at least as long. Unknown types aren't blocked.
export const canReportAtPeriodType = (
    dataSetPeriodType: string,
    periodType: string
) => {
    const collected = LENGTH_IN_DAYS[dataSetPeriodType]
    const asked = LENGTH_IN_DAYS[periodType]
    return !collected || !asked || asked >= collected
}

// shown once Get report has been pressed with the field still empty
const useRequiredField = (name: string) => {
    const field = useField<string>(name, {
        subscription: { value: true, error: true, submitFailed: true },
    })
    const { error, submitFailed } = field.meta
    return {
        input: field.input,
        error: submitFailed && error ? (error as string) : undefined,
    }
}

const DataSetField = ({
    dataSets,
    loading,
}: {
    dataSets: DataSet[]
    loading: boolean
}) => {
    const { input, error } = useRequiredField('ds')
    // until the list arrives, the select can't show the selected data set
    const dataSet = dataSets.find(({ id }) => id === input.value)
    return (
        <>
            <SingleSelectField
                filterable
                noMatchText="No data sets match"
                // the group title above is this field's label
                aria-label="Data set"
                placeholder="Choose a data set"
                error={Boolean(error)}
                validationText={error}
                loading={loading}
                selected={dataSet?.id}
                onChange={({ selected }) => input.onChange(selected)}
            >
                {dataSets.map(({ id, displayName }) => (
                    <SingleSelectOption
                        key={id}
                        value={id}
                        label={displayName}
                    />
                ))}
            </SingleSelectField>
            {dataSet && (
                <p className={styles.help}>
                    {cadenceLabel(dataSet.periodType)}
                </p>
            )}
        </>
    )
}

/*
 * One select per attribute category (e.g. Project), as the prototype's data
 * set dimensions. Optional for the summary, which adds up all options when
 * none is chosen; the form needs one for each.
 */
const AttributeFields = ({
    categories,
    neededForForm,
}: {
    // undefined until the data sets list has loaded
    categories?: AttributeCategory[]
    neededForForm: boolean
}) => {
    const { input } = useField<Record<string, string>>('attributes', {
        subscription: { value: true },
    })
    const attributes = input.value || {}

    // options of another data set's categories don't apply to this one
    const categoryIds = categories?.map(({ id }) => id).join()
    useEffect(() => {
        if (!categories) {
            return
        }
        const kept = Object.fromEntries(
            Object.entries(attributes).filter(([id]) =>
                categories.some((category) => category.id === id)
            )
        )
        if (Object.keys(kept).length !== Object.keys(attributes).length) {
            input.onChange(kept)
        }
    }, [categoryIds])

    if (!categories || categories.length === 0) {
        return null
    }
    return (
        <div className={styles.periodFields}>
            {categories.map(({ id, displayName, categoryOptions }) => (
                <SingleSelectField
                    key={id}
                    clearable
                    filterable
                    noMatchText="No options match"
                    label={displayName}
                    placeholder="All"
                    warning={neededForForm && !attributes[id]}
                    validationText={
                        neededForForm && !attributes[id]
                            ? 'Choose one to see the data entry form'
                            : undefined
                    }
                    selected={
                        categoryOptions.some(
                            (option) => option.id === attributes[id]
                        )
                            ? attributes[id]
                            : undefined
                    }
                    onChange={({ selected }) => {
                        const next = { ...attributes }
                        if (selected) {
                            next[id] = selected
                        } else {
                            delete next[id]
                        }
                        input.onChange(next)
                    }}
                >
                    {categoryOptions.map((option) => (
                        <SingleSelectOption
                            key={option.id}
                            value={option.id}
                            label={option.displayName}
                        />
                    ))}
                </SingleSelectField>
            ))}
        </div>
    )
}

type PeriodTypeOption = { name: string; displayName: string }

/*
 * Type, year, then period, like the prototype. The type starts on the data
 * set's own; longer types are fine (the report adds the data up), shorter ones
 * are disabled because data can't be split into a shorter period.
 */
const PeriodField = ({
    dataSetPeriodType,
    periodTypes,
}: {
    dataSetPeriodType?: string
    periodTypes: PeriodTypeOption[]
}) => {
    const calendar = useCalendar()
    const { input, error } = useRequiredField('pe')
    const current = input.value ? parsePeriod(input.value, calendar) : undefined
    // the period's type as a DHIS2 name ("Monthly"), not the
    // multi-calendar-dates one ("MONTHLY")
    const currentType = PERIODS_ORDER.find(
        (name) => toMultiCalendarPeriodType(name) === current?.periodType
    )
    const allowed = (type?: string) =>
        Boolean(
            type &&
                dataSetPeriodType &&
                canReportAtPeriodType(dataSetPeriodType, type)
        )

    const [periodType, setPeriodType] = useState(() =>
        allowed(currentType) ? currentType : dataSetPeriodType
    )
    const [year, setYear] = useState(() =>
        current
            ? parseInt(current.startDate.split('-')[0], 10)
            : new Date().getFullYear()
    )
    const periods = useFixedPeriods({ periodType: periodType ?? '', year })
    const thisYear = new Date().getFullYear()
    const years = Array.from(
        new Set([
            ...Array.from(
                { length: YEARS_OF_HISTORY },
                (_, index) => thisYear - index
            ),
            year,
        ])
    ).sort((a, b) => b - a)

    // A different data set can have a longer period type, which the old
    // period may be too short for.
    useEffect(() => {
        // the data sets list may not have arrived yet
        if (dataSetPeriodType && currentType && !allowed(currentType)) {
            input.onChange(undefined)
        }
    }, [dataSetPeriodType])

    if (!dataSetPeriodType) {
        return <p className={styles.hint}>Choose a data set first</p>
    }

    const selected = periods.some(({ value }) => value === input.value)
        ? input.value
        : undefined
    return (
        <div className={styles.periodFields}>
            <SingleSelectField
                // "Period" is the group title above
                label="Type"
                placeholder="Choose a type"
                selected={
                    periodTypes.some(({ name }) => name === periodType)
                        ? periodType
                        : undefined
                }
                onChange={({ selected }) => {
                    input.onChange(undefined)
                    setPeriodType(selected)
                }}
            >
                {periodTypes.map(({ name, displayName }) => (
                    <SingleSelectOption
                        key={name}
                        value={name}
                        label={displayName}
                        disabled={!allowed(name)}
                    />
                ))}
            </SingleSelectField>
            <SingleSelectField
                filterable
                noMatchText="No year found"
                label="Year"
                selected={String(year)}
                onChange={({ selected }) => {
                    input.onChange(undefined)
                    setYear(Number(selected))
                }}
            >
                {years.map((option) => (
                    <SingleSelectOption
                        key={option}
                        value={String(option)}
                        label={String(option)}
                    />
                ))}
            </SingleSelectField>
            <SingleSelectField
                label="Period"
                placeholder="Choose a period"
                error={Boolean(error)}
                validationText={error}
                selected={selected}
                disabled={periods.length === 0}
                onChange={({ selected }) => input.onChange(selected)}
            >
                {periods.map(({ value, label }) => (
                    <SingleSelectOption
                        key={value}
                        value={value}
                        label={label}
                    />
                ))}
            </SingleSelectField>
        </div>
    )
}

// "/a/b/c" -> ["/a", "/a/b"], so the tree opens with the unit in view
const ancestorPaths = (path: string) => {
    const ids = path.split('/').filter(Boolean)
    return ids.slice(0, -1).map((_, i) => `/${ids.slice(0, i + 1).join('/')}`)
}

const OrgUnitField = () => {
    const { organisationUnits: roots } = useUserContext()
    const { input, error } = useRequiredField('ou')
    const { input: unitOnly } = useField<boolean>('selectedUnitOnly', {
        subscription: { value: true },
    })
    // The form holds an ID but the tree selects by path, so look up the path
    // of the initial org unit (e.g. from the URL) once.
    const [initialId] = useState(input.value)
    const { data, loading } = useDataQuery<{ orgUnit: { path: string } }>(
        ORG_UNIT_PATH_QUERY,
        { variables: { id: initialId }, lazy: !initialId }
    )
    const [path, setPath] = useState<string>()
    const selectedPath = path ?? data?.orgUnit.path

    if (loading) {
        return <CircularLoader small />
    }
    return (
        <>
            <div
                className={
                    error
                        ? `${styles.treeCard} ${styles.treeCardError}`
                        : styles.treeCard
                }
            >
                <div className={styles.treeBox}>
                    <OrganisationUnitTree
                        roots={roots}
                        singleSelection
                        selected={selectedPath ? [selectedPath] : []}
                        initiallyExpanded={
                            selectedPath ? ancestorPaths(selectedPath) : roots
                        }
                        onChange={({ id, path, selected }) => {
                            const isSelected = selected.length > 0
                            setPath(isSelected ? path : '')
                            input.onChange(isSelected ? id : undefined)
                        }}
                    />
                </div>
                <fieldset className={styles.treeFooter}>
                    <legend className={styles.srOnly}>Selection mode</legend>
                    <Radio
                        dense
                        name="selectedUnitOnly"
                        label="Include units inside"
                        checked={!unitOnly.value}
                        onChange={() => unitOnly.onChange(false)}
                    />
                    <Radio
                        dense
                        name="selectedUnitOnly"
                        label="Selection only"
                        checked={Boolean(unitOnly.value)}
                        onChange={() => unitOnly.onChange(true)}
                    />
                </fieldset>
            </div>
            {error && <p className={styles.error}>{error}</p>}
        </>
    )
}

export const SpikeParameters = ({
    spikeDetails,
    formView,
}: {
    spikeDetails: React.ReactNode
    formView: boolean
}) => {
    const { data, loading, error } = useDataQuery<{
        dataSets: { dataSets: DataSet[] }
    }>(DATA_SETS_QUERY)
    const dataSets = data?.dataSets.dataSets ?? []
    const { data: periodTypesData } = useDataQuery<{
        periodTypes: { periodTypes: PeriodTypeOption[] }
    }>(PERIOD_TYPES_QUERY)
    const periodTypes = (periodTypesData?.periodTypes.periodTypes ?? [])
        .filter(({ name }) => PERIODS_ORDER.includes(name))
        .sort(
            (a, b) =>
                PERIODS_ORDER.indexOf(a.name) - PERIODS_ORDER.indexOf(b.name)
        )

    const { input: dsInput } = useField<string>('ds', {
        subscription: { value: true },
    })
    const dataSet = dataSets.find(({ id }) => id === dsInput.value)
    const periodType = dataSet?.periodType
    const attributeCategories = !dataSet
        ? undefined
        : dataSet.categoryCombo.isDefault
        ? []
        : dataSet.categoryCombo.categories

    return (
        <>
            <ParameterItem title="Organisation unit">
                <OrgUnitField />
            </ParameterItem>
            <ParameterItem title="Data set">
                {error ? (
                    <p className={styles.hint}>{error.message}</p>
                ) : (
                    <DataSetField dataSets={dataSets} loading={loading} />
                )}
                <AttributeFields
                    categories={attributeCategories}
                    neededForForm={formView}
                />
            </ParameterItem>
            <ParameterItem title="Period">
                {/* remount on a new data set period type, so the type and
                 * year start over from it */}
                <PeriodField
                    key={periodType}
                    dataSetPeriodType={periodType}
                    periodTypes={periodTypes}
                />
            </ParameterItem>
            {spikeDetails}
        </>
    )
}
