import { useConfig, useDataQuery } from '@dhis2/app-runtime'
import {
    convertToIso8601,
    createFixedPeriodFromPeriodId,
    getAdjacentFixedPeriods,
    getFixedPeriodByDate,
    getNowInCalendar,
} from '@dhis2/multi-calendar-dates'
import { useEffect, useState } from 'react'
import {
    toDhis2PeriodId,
    toLibraryPeriodId,
    toMultiCalendarPeriodType,
} from '@/pages/StandardReport/view/parametersSelector/fixedPeriods/periodTypeMapping'
import type { DynamicResourceQuery, QueryVariables } from '@/types/query'

/*
 * SPIKE (DHIS2-22048): checks a selection with the data entry app's rules
 * (org unit assignment, open periods, attribute options) before anything is
 * sent to the plugin, which can't correct a selection without its top bar.
 */

// not exported by @dhis2/multi-calendar-dates, so derived structurally from
// a function that uses it
type SupportedCalendar = Parameters<
    typeof createFixedPeriodFromPeriodId
>[0]['calendar']

type CategoryOption = {
    id: string
    displayName: string
    startDate?: string
    endDate?: string
    organisationUnits?: { id: string }[]
}

type Category = {
    id: string
    displayName: string
    categoryOptions: CategoryOption[]
}

type FormDataSet = {
    displayName: string
    periodType: string
    dataSetElements?: { dataElement: { id: string } }[]
    openFuturePeriods?: number
    openPeriodsAfterCoEndDate?: number
    access: { data: { read: boolean } }
    categoryCombo: { id: string; isDefault: boolean; categories: Category[] }
}

type FormSelectionResponse = {
    dataSet: FormDataSet
    assigned: { dataSets: { id: string }[] }
    orgUnit: { path: string }
}

const FORM_SELECTION_QUERY: Record<string, DynamicResourceQuery> = {
    dataSet: {
        resource: 'dataSets',
        id: ({ ds }: QueryVariables) => ds,
        params: {
            fields: 'displayName,periodType,openFuturePeriods,openPeriodsAfterCoEndDate,access[data[read]],dataSetElements[dataElement[id]],categoryCombo[id,isDefault,categories[id,displayName,categoryOptions[id,displayName,startDate,endDate,organisationUnits[id]]]]',
        },
    },
    // empty unless the org unit is assigned
    assigned: {
        resource: 'dataSets',
        params: ({ ds, ou }: QueryVariables) => ({
            filter: [`id:eq:${ds}`, `organisationUnits.id:eq:${ou}`],
            fields: 'id',
            paging: false,
        }),
    } as unknown as DynamicResourceQuery,
    orgUnit: {
        resource: 'organisationUnits',
        id: ({ ou }: QueryVariables) => ou,
        params: { fields: 'path' },
    },
}

export type Selection = {
    ds: string
    ou: string
    pe: string
    // { categoryId: optionId }
    attributes: Record<string, string>
}

const parsePeriod = (periodId: string, calendar: SupportedCalendar) => {
    try {
        return createFixedPeriodFromPeriodId({
            periodId: toLibraryPeriodId(periodId),
            calendar,
        })
    } catch {
        return undefined
    }
}

const pad = (value: number, length: number) =>
    String(value).padStart(length, '0')

const todayInCalendar = (calendar: SupportedCalendar, timezone: string) => {
    const now = getNowInCalendar(calendar, timezone)
    const year = ['ethiopian', 'ethiopic'].includes(calendar)
        ? now.eraYear ?? now.year
        : now.year
    return `${pad(year, 4)}-${pad(now.month, 2)}-${pad(now.day, 2)}`
}

// category option dates are ISO; period dates are in the system calendar
const toIso = (date: string, calendar: SupportedCalendar) => {
    if (calendar === 'gregory') {
        return date
    }
    const iso = convertToIso8601(date, calendar)
    return `${pad(iso.year, 4)}-${pad(iso.month, 2)}-${pad(iso.day, 2)}`
}

// the first date the data set doesn't take data for (use-date-limit.js)
const dateLimit = (
    dataSet: Pick<FormDataSet, 'periodType' | 'openFuturePeriods'>,
    calendar: SupportedCalendar,
    timezone: string
) => {
    const periodType = toMultiCalendarPeriodType(dataSet.periodType)
    const current = getFixedPeriodByDate({
        periodType,
        date: todayInCalendar(calendar, timezone),
        calendar,
    })
    const open = dataSet.openFuturePeriods ?? 0
    if (open <= 0) {
        return current.startDate
    }
    const following = getAdjacentFixedPeriods({
        period: current,
        calendar,
        steps: open,
    })
    return following[following.length - 1].startDate
}

// openPeriodsAfterCoEndDate is applied by comparing an option's end date
// with the end of a period that many periods earlier
const validOptions = ({
    dataSet,
    period,
    orgUnitPath,
    calendar,
}: {
    dataSet: FormDataSet
    period: NonNullable<ReturnType<typeof parsePeriod>>
    orgUnitPath: string
    calendar: SupportedCalendar
}) => {
    const after = Math.max(dataSet.openPeriodsAfterCoEndDate ?? 0, 0)
    const earlier = after
        ? getAdjacentFixedPeriods({ period, calendar, steps: -after - 1 })
        : []
    const start = toIso(period.startDate, calendar)
    const end = toIso(earlier[0]?.endDate ?? period.endDate, calendar)
    const ancestors = orgUnitPath.split('/').filter(Boolean)

    return dataSet.categoryCombo.categories.map((category) => ({
        ...category,
        categoryOptions: category.categoryOptions.filter(
            ({ startDate, endDate, organisationUnits }) =>
                (!startDate || startDate.slice(0, 10) <= start) &&
                (!endDate || endDate.slice(0, 10) >= end) &&
                (!organisationUnits?.length ||
                    organisationUnits.some(({ id }) => ancestors.includes(id)))
        ),
    }))
}

export type FormPeriod = { id: string; displayName: string }

const MAX_FORM_PERIODS = 400

// the data set's periods starting within a longer period; empty otherwise
export const periodsWithin = (
    periodId: string,
    dataSetPeriodType: string,
    calendar: SupportedCalendar
): FormPeriod[] => {
    const period = periodId ? parsePeriod(periodId, calendar) : undefined
    const periodType = toMultiCalendarPeriodType(dataSetPeriodType)
    if (!period || period.periodType === periodType) {
        return []
    }
    let current = getFixedPeriodByDate({
        periodType,
        date: period.startDate,
        calendar,
    })
    if (current.startDate < period.startDate) {
        ;[current] = getAdjacentFixedPeriods({
            period: current,
            calendar,
            steps: 1,
        })
    }
    const within: FormPeriod[] = []
    while (
        current.startDate <= period.endDate &&
        within.length < MAX_FORM_PERIODS
    ) {
        within.push({
            id: toDhis2PeriodId(current.id),
            displayName: current.displayName,
        })
        ;[current] = getAdjacentFixedPeriods({
            period: current,
            calendar,
            steps: 1,
        })
    }
    const [first] = within
    const firstPeriod = first ? parsePeriod(first.id, calendar) : undefined
    return firstPeriod && firstPeriod.endDate <= period.endDate ? within : []
}

export type FormProblem =
    | { field: 'ds' | 'ou' | 'pe'; message: string }
    | { field: 'attributes'; categoryId: string; message: string }

type Context = {
    calendar: SupportedCalendar
    timezone: string
}

// why the selection has no form, or [] when it has one
export const formProblems = (
    {
        dataSet,
        assigned,
        orgUnit,
    }: Pick<FormSelectionResponse, 'dataSet' | 'assigned' | 'orgUnit'>,
    {
        pe,
        attributes,
        calendar,
        timezone,
    }: Pick<Selection, 'pe' | 'attributes'> & Context
): FormProblem[] => {
    if (!dataSet.access.data.read) {
        return [
            {
                field: 'ds',
                message: `You don't have access to the data of ${dataSet.displayName}.`,
            },
        ]
    }
    const problems: FormProblem[] = []
    if (assigned.dataSets.length === 0) {
        problems.push({
            field: 'ou',
            message: `${dataSet.displayName} isn't collected at this organisation unit. The summary can add up the units inside it; the form is for a unit that collects the data.`,
        })
    }
    if (!pe) {
        return problems
    }

    const period = parsePeriod(pe, calendar)
    const ofDataSetsType =
        period?.periodType === toMultiCalendarPeriodType(dataSet.periodType)
    const totals =
        !ofDataSetsType &&
        periodsWithin(pe, dataSet.periodType, calendar).length > 0
    if (!period || (!ofDataSetsType && !totals)) {
        problems.push({
            field: 'pe',
            message: `${dataSet.displayName} is collected ${dataSet.periodType}. The form can't show a shorter period.`,
        })
        return problems
    }
    // totals need only the first of their periods to be open
    const limit = dateLimit(dataSet, calendar, timezone)
    if ((totals ? period.startDate : period.endDate) >= limit) {
        problems.push({
            field: 'pe',
            message: `${period.displayName} isn't open for data entry yet.`,
        })
    }

    if (dataSet.categoryCombo.isDefault) {
        return problems
    }
    const categories = validOptions({
        dataSet,
        period,
        orgUnitPath: orgUnit.path,
        calendar,
    })
    for (const { id, displayName, categoryOptions } of categories) {
        let message
        if (categoryOptions.length === 0) {
            message = `No ${displayName} option is open for this period and organisation unit.`
        } else if (!attributes[id]) {
            message = `Choose a ${displayName} to see the data entry form. It shows the values entered for one option; the summary adds them all up.`
        } else if (!categoryOptions.some(({ id: o }) => o === attributes[id])) {
            message = `The chosen ${displayName} isn't open for this period and organisation unit.`
        }
        if (message) {
            problems.push({ field: 'attributes', categoryId: id, message })
        }
    }
    return problems
}

// as use-data-value-set-query-key.js builds them
export type DataValuesParams = {
    ds: string
    pe: string
    ou: string
    cc?: string
    cp?: string
}

const toDataValuesParams = (
    { ds, pe, ou, attributes }: Selection,
    categoryCombo: FormDataSet['categoryCombo']
): DataValuesParams =>
    categoryCombo.isDefault
        ? { ds, pe, ou }
        : {
              ds,
              pe,
              ou,
              cc: categoryCombo.id,
              cp: Object.values(attributes).sort().join(';'),
          }

type Checked = {
    key: string
    data?: FormSelectionResponse
    error?: string
}

const NOT_CHECKED = {
    checking: false,
    problems: [] as FormProblem[],
    ready: false,
    openOptions: undefined as Record<string, string[]> | undefined,
    isPeriodOpen: undefined as ((periodId: string) => boolean) | undefined,
    dataValuesParams: undefined as DataValuesParams | undefined,
    totals: false,
    formSelection: undefined as Selection | undefined,
    // for the totals request
    dataElements: undefined as string[] | undefined,
}

export const useFormSelection = (selection?: Selection) => {
    const { systemInfo } = useConfig() as {
        systemInfo?: { calendar?: string; serverTimeZoneId?: string }
    }
    const calendar = (systemInfo?.calendar ?? 'gregory') as SupportedCalendar
    const timezone = systemInfo?.serverTimeZoneId ?? 'Etc/UTC'
    const { refetch } = useDataQuery<FormSelectionResponse>(
        FORM_SELECTION_QUERY,
        { lazy: true }
    )

    // keyed, so a selection is never checked against another one's metadata
    const ds = selection?.ds
    const ou = selection?.ou
    const key = ds && ou ? `${ds}:${ou}` : ''
    const [checked, setChecked] = useState<Checked>()
    useEffect(() => {
        if (!ds || !ou) {
            return
        }
        let current = true
        refetch({ ds, ou })
            .then((data) => {
                if (current) {
                    setChecked({
                        key: `${ds}:${ou}`,
                        data: data as FormSelectionResponse,
                    })
                }
            })
            .catch((error: Error) => {
                if (current) {
                    setChecked({ key: `${ds}:${ou}`, error: error.message })
                }
            })
        return () => {
            current = false
        }
    }, [ds, ou, refetch])

    if (!selection || !key) {
        return NOT_CHECKED
    }
    if (checked?.key !== key) {
        return { ...NOT_CHECKED, checking: true }
    }
    const { data } = checked
    if (!data) {
        return {
            ...NOT_CHECKED,
            problems: [
                {
                    field: 'ds',
                    message: `The data entry form can't be shown for this selection (${checked.error}).`,
                } as FormProblem,
            ],
        }
    }

    const problems = formProblems(data, {
        ...selection,
        calendar,
        timezone,
    })
    const limit = dateLimit(data.dataSet, calendar, timezone)
    const period = selection.pe
        ? parsePeriod(selection.pe, calendar)
        : undefined
    const ready = Boolean(selection.pe) && problems.length === 0
    const periodIsDataSets =
        period?.periodType ===
        toMultiCalendarPeriodType(data.dataSet.periodType)
    return {
        checking: false,
        problems,
        ready,
        totals:
            ready &&
            periodsWithin(selection.pe, data.dataSet.periodType, calendar)
                .length > 0,
        formSelection: ready ? selection : undefined,
        dataElements: ready
            ? (data.dataSet.dataSetElements ?? []).map(
                  ({ dataElement }) => dataElement.id
              )
            : undefined,
        dataValuesParams: ready
            ? toDataValuesParams(selection, data.dataSet.categoryCombo)
            : undefined,
        openOptions:
            period && periodIsDataSets && !data.dataSet.categoryCombo.isDefault
                ? Object.fromEntries(
                      validOptions({
                          dataSet: data.dataSet,
                          period,
                          orgUnitPath: data.orgUnit.path,
                          calendar,
                      }).map(({ id, categoryOptions }) => [
                          id,
                          categoryOptions.map((option) => option.id),
                      ])
                  )
                : undefined,
        isPeriodOpen: (periodId: string) => {
            const candidate = parsePeriod(periodId, calendar)
            return Boolean(candidate && candidate.endDate < limit)
        },
    }
}
