import i18n from '@dhis2/d2-i18n'
import { Button, IconAdd16 } from '@dhis2/ui'
import React, { useCallback, useState } from 'react'
import { Link } from 'react-router-dom'
import styles from './overview.module.css'
import { ReportsSearchField } from './ReportsSearch/reportsSearchField'
import {
    NoMatches,
    ReportCard,
    ReportsList,
    ReportsListManageView,
} from './ReportsView'
import { useReports } from './useReports'

const BUILT_IN_REPORTS = [
    {
        title: i18n.t('Data set report'),
        linkDestination: 'dataSetReports',
        description: i18n.t('View or print data entered for a data set.'),
    },
]

const BuiltInReports = ({ searchTerm }: { searchTerm: undefined | string }) => {
    const filteredReports = BUILT_IN_REPORTS.filter((report) => {
        return !searchTerm
            ? true
            : report.title.toLowerCase().includes(searchTerm.toLowerCase())
    })
    return (
        <section className={styles.group}>
            <div className={styles.groupHeader}>
                <span className={styles.groupTitle}>
                    {i18n.t('Built-in reports')}
                </span>
            </div>
            <div className={styles.grid}>
                {filteredReports.length === 0 ? (
                    <NoMatches searchTerm={searchTerm} />
                ) : (
                    filteredReports.map((report) => (
                        <ReportCard
                            title={report.title}
                            linkDestination="dataSetReports"
                            description={report.description}
                        />
                    ))
                )}
            </div>
        </section>
    )
}

export const Overview = ({ manageView = false }: { manageView?: boolean }) => {
    const { reports, refetchReports, pager, loading, error } = useReports()
    const [searchTerm, setSearchTerm] = useState<undefined | string>(
        () => undefined
    )
    const [order, setOrderString] = useState<string>('displayName:iasc')
    const setOrder = useCallback(
        (nextOrder: string) => {
            setOrderString(nextOrder)
            refetchReports({
                searchTerm,
                order: nextOrder,
                pageSize: pager?.pageSize,
                page: pager?.page,
            })
        },
        [refetchReports, searchTerm, pager?.pageSize, pager?.page]
    )

    return (
        <div className={manageView ? styles.managePage : styles.page}>
            <div className={styles.searchBar}>
                <ReportsSearchField
                    refetchReports={refetchReports}
                    searchTerm={searchTerm}
                    setSearchTerm={setSearchTerm}
                    order={order}
                />
                {manageView && (
                    <Link to="/standardReports/new">
                        <Button icon={<IconAdd16 />}>
                            {i18n.t('New standard report')}
                        </Button>
                    </Link>
                )}
            </div>
            {manageView ? null : <BuiltInReports searchTerm={searchTerm} />}

            {manageView ? (
                <ReportsListManageView
                    reports={reports}
                    loading={loading}
                    error={error}
                    searchTerm={searchTerm}
                    pager={pager}
                    refetchReports={refetchReports}
                    order={order}
                    setOrder={setOrder}
                />
            ) : (
                <ReportsList
                    reports={reports}
                    loading={loading}
                    error={error}
                    searchTerm={searchTerm}
                    pager={pager}
                    refetchReports={refetchReports}
                />
            )}
        </div>
    )
}
