import { CssVariables, CssReset } from '@dhis2/ui'
import React from 'react'
import {
    createHashRouter,
    RouterProvider,
    Outlet,
    Route,
    createRoutesFromElements,
} from 'react-router-dom'
import { QueryParamProvider } from 'use-query-params'
import { ReactRouter6Adapter } from 'use-query-params/adapters/react-router-6'
import styles from './App.module.css'
import { UserProvider } from './context/index'
import { FormPluginSpike } from './pages/DataSetReport/spike/FormPluginSpike'
import {
    Overview,
    DataSetReportView,
    StandardReportView,
    StandardReportEdit,
    StandardReportManage,
    StandardReportAdd,
} from './pages/index'

const routes = createRoutesFromElements(
    <>
        <Route
            element={
                <QueryParamProvider adapter={ReactRouter6Adapter}>
                    {/* <SyncUrlWithGlobalShell /> */}
                    <Outlet />
                </QueryParamProvider>
            }
            errorElement={<p>error</p>}
        >
            <Route path="/" element={<Overview />}></Route>
            <Route
                path="/standardReports/view/:reportId"
                element={<StandardReportView />}
            ></Route>
            <Route
                path="/standardReports/edit/:reportId"
                element={<StandardReportEdit />}
            ></Route>
            <Route
                path="/standardReports/new"
                element={<StandardReportAdd />}
            ></Route>
            <Route
                path="/standardReports/manage"
                element={<StandardReportManage />}
            ></Route>
            <Route
                path="/dataSetReports"
                element={<DataSetReportView />}
            ></Route>
            {/* SPIKE (DHIS2-22048) */}
            <Route
                path="/dataSetReports/spike/form-plugin"
                element={<FormPluginSpike />}
            ></Route>
        </Route>
    </>
)

export const hashRouter = createHashRouter(routes)
const ConfiguredRouter = () => {
    return <RouterProvider router={hashRouter} />
}

const AppLayout = ({ children }: { children: React.ReactNode }) => {
    return <div className={styles.container}>{children}</div>
}

export const AppWrapper = ({ children }: { children: React.ReactNode }) => {
    return (
        <UserProvider>
            <CssReset />
            <CssVariables theme spacers colors elevations />
            <AppLayout>{children}</AppLayout>
        </UserProvider>
    )
}

const App = () => (
    <AppWrapper>
        <ConfiguredRouter />
    </AppWrapper>
)

export default App
